import colorsys

def hex_to_rgb(h):
    h = h.lstrip('#')
    return tuple(int(h[i:i+2],16)/255 for i in (0,2,4))

def rgb_to_hex(rgb):
    return '#%02x%02x%02x' % tuple(round(c*255) for c in rgb)

r,g,b = hex_to_rgb('bfdc99')
