        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });
  });
}

// ===== 品牌故事照片輪播（24張，依教練下載順序，每4秒切換一張） =====
function initPhotoCarousel() {
  const wrap = document.getElementById('photoCarousel');
  if (!wrap) return;
  const total = 24;
  let current = 0;
  const slides = [];
  for (let i = 1; i <= total; i++) {
    const n = String(i).padStart(2, '0');
    const img = document.createElement('img');
    img.src = `photos-carousel/photo-${n}.jpg`;
    img.alt = `大樹教練活動照片 ${i}`;
    img.className = 'absolute inset-0 w-full h-full object-cover transition-opacity duration-1000';
    img.style.opacity = i === 1 ? '1' : '0';
    wrap.appendChild(img);
    slides.push(img);
  }
  setInterval(() => {
    slides[current].style.opacity = '0';
    current = (current + 1) % total;
    slides[current].style.opacity = '1';
  }, 4000);
}

buildSessions();
initNavbar();
initSmoothScroll();
initPhotoCarousel();

